package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="patient_consents",uniqueConstraints=@UniqueConstraint(columnNames={"patient_id","consent_type"}))
public class Consent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="patient_id",nullable=false) private User patient; @Column(name="consent_type",nullable=false,length=80) private String consentType; @Column(nullable=false) private boolean granted; @Column(length=500) private String purpose; private LocalDateTime updatedAt; @PrePersist @PreUpdate void c(){updatedAt=LocalDateTime.now();} public Consent(){} public Consent(User p,String t,boolean g,String purpose){patient=p;consentType=t;granted=g;this.purpose=purpose;} public Long getId(){return id;} public User getPatient(){return patient;} public String getConsentType(){return consentType;} public boolean isGranted(){return granted;} public void setGranted(boolean v){granted=v;} public String getPurpose(){return purpose;} public LocalDateTime getUpdatedAt(){return updatedAt;} }
